SELECT task_profile_id, model_id, provider_id, hosted, trusted_lan, COUNT(*)::BIGINT AS call_count, COUNT(*) FILTER (WHERE status = 'failed')::BIGINT AS failure_count, COALESCE(AVG(latency_ms), 0)::BIGINT AS average_latency_ms, SUM(input_tokens)::BIGINT AS input_tokens, SUM(output_tokens)::BIGINT AS output_tokens, SUM(estimated_cost_usd)::DOUBLE PRECISION AS estimated_cost_usd, MAX(created_at)::TEXT AS last_used_at FROM model_inference_runs GROUP BY task_profile_id, model_id, provider_id, hosted, trusted_lan ORDER BY MAX(created_at) DESC LIMIT $1
